class Solution:
    def minPushBox(self, grid):
        m, n = len(grid), len(grid[0])
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 'S': start = (i, j)
                elif grid[i][j] == 'B': box = (i, j)
                elif grid[i][j] == 'T': target = (i, j)
        def can_reach(src, dst, box_pos):
            if src == dst: return True
            visited = {src}
            q = deque([src])
            while q:
                x, y = q.popleft()
                for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx, ny = x+dx, y+dy
                    if 0<=nx<m and 0<=ny<n and (nx,ny) not in visited and grid[nx][ny]!='#' and (nx,ny)!=box_pos:
                        if (nx,ny)==dst: return True
                        visited.add((nx,ny))
                        q.append((nx,ny))
            return False
        q = deque([(0, box, start)])
        visited = {(box, start)}
        while q:
            pushes, bpos, ppos = q.popleft()
            if bpos == target: return pushes
            bx, by = bpos
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nbx, nby = bx+dx, by+dy
                player_need = (bx-dx, by-dy)
                if 0<=nbx<m and 0<=nby<n and grid[nbx][nby]!='#' and 0<=player_need[0]<m and 0<=player_need[1]<n and grid[player_need[0]][player_need[1]]!='#':
                    new_state = ((nbx,nby), bpos)
                    if new_state not in visited and can_reach(ppos, player_need, bpos):
                        visited.add(new_state)
                        q.append((pushes+1, (nbx,nby), bpos))
        return -1

