class Solution:
    def maxCandies(self, status, candies, keys, containedBoxes, initialBoxes):
        have_box = set(initialBoxes)
        have_key = set(i for i in range(len(status)) if status[i])
        q = deque([b for b in initialBoxes if b in have_key])
        opened = set(q)
