class Solution:
    def findBestValue(self, arr, target):
        arr.sort()
        n = len(arr)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + arr[i]
        def compute(val):
            import bisect
            idx = bisect.bisect_right(arr, val)
            return prefix[idx] + val * (n - idx)
        lo, hi = 0, max(arr)
        while lo < hi:
            mid = (lo + hi) // 2
            if compute(mid) >= target:
                hi = mid
            else:
                lo = mid + 1
        if abs(compute(lo) - target) < abs(compute(lo-1) - target):
            return lo
        return lo - 1

class Solution:
    def pathsWithMaxScore(self, board):
        MOD = 10**9 + 7
        n = len(board)
        dp = [[[-1, 0] for _ in range(n+1)] for _ in range(n+1)]
        dp[n-1][n-1] = [0, 1]
        for i in range(n-1, -1, -1):
            for j in range(n-1, -1, -1):
                if (i == n-1 and j == n-1) or board[i][j] == 'X':
                    continue
                for di, dj in [(1,0),(0,1),(1,1)]:
                    ni, nj = i+di, j+dj
                    if ni < n and nj < n and dp[ni][nj][1] > 0:
                        val = dp[ni][nj][0] + (int(board[i][j]) if board[i][j].isdigit() else 0)
                        if val > dp[i][j][0]:
                            dp[i][j] = [val, dp[ni][nj][1]]
                        elif val == dp[i][j][0]:
                            dp[i][j][1] = (dp[i][j][1] + dp[ni][nj][1]) % MOD
        return [dp[0][0][0] % MOD, dp[0][0][1] % MOD] if dp[0][0][1] > 0 else [0, 0]

