class Solution:
    def isSolvable(self, words, result):
        from itertools import permutations
        letters = set()
        for w in words + [result]:
            letters.update(w)
        letters = list(letters)
        non_zero = set(w[0] for w in words + [result] if len(w) > 1)
        for perm in permutations(range(10), len(letters)):
            mapping = dict(zip(letters, perm))
            if any(mapping[c] == 0 for c in non_zero):
                continue
            word_vals = [sum(mapping[c] * 10**i for i, c in enumerate(reversed(w))) for w in words]
