class Solution:
    def makeConnected(self, n, connections):
        if len(connections) < n - 1: return -1
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        components = n
        for a, b in connections:
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
                components -= 1
        return components - 1

class Solution:
    def minimumDistance(self, word):
        def dist(a, b):
            if a == -1: return 0
            r1, c1 = a // 6, a % 6
            r2, c2 = b // 6, b % 6
            return abs(r1-r2) + abs(c1-c2)
        n = len(word)
        # dp[j] = min cost when the other finger is at position j, -1 means not placed
        dp = {-1: 0}
        prev = -1
        for i in range(n):
            cur = ord(word[i]) - ord('A')
            new_dp = {}
            for other, cost in dp.items():
                # Move the finger that was at prev to cur
                key = other
                val = cost + dist(prev, cur)
                if key not in new_dp or val < new_dp[key]:
                    new_dp[key] = val
                # Move the other finger to cur
                key2 = prev
                val2 = cost + dist(other, cur)
                if key2 not in new_dp or val2 < new_dp[key2]:
                    new_dp[key2] = val2
            dp = new_dp
            prev = cur
        return min(dp.values())
